package net.officefloor.hq.app.period;

import java.util.Map;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Reopens a closed or soft-closed period, so its due-total is live again; only a role the sheet's reopen permission gives may (a steward while blank), and a period still open is refused.
 */
public class ReopenPeriod {
    public void reopen(@Val Period period, @Val ChangedBy by, PeriodRepository repository, RoleRepository roles,
            SettingRepository settings, Out<ReopenedPeriod> reopened) throws BadRequestException {
        String role = roles.roleOf(period.sheetId(), by.name());
        if (!settings.allows(period.sheetId(), "reopen", role)) {
            throw new BadRequestException("A " + role + " may not reopen a period on this sheet");
        }
        if (!period.closed() && !period.soft()) {
            throw new BadRequestException("That period is not closed");
        }
        if (!repository.reopen(period.id())) {
            throw new BadRequestException("The period was reopened by someone else; reload the sheet");
        }
        reopened.set(new ReopenedPeriod(new Period(period.id(), period.sheetId(), period.name(), period.from(),
                period.to(), false, null, Map.of(), false)));
    }
}
package net.officefloor.hq.app.access;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The roles assigned on each sheet; a user name without one is a clerk. */
@Repository
public class RoleRepository {

    private static final RowMapper<Role> ROW = (rs, n) -> new Role(rs.getString("sheet_id"),
            rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;

    private final DelegationRepository delegations;

    public RoleRepository(JdbcTemplate jdbc, DelegationRepository delegations) {
        this.jdbc = jdbc;
        this.delegations = delegations;
    }

    /** The sheet's assigned roles, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name", ROW,
                sheetId);
    }

    /**
     * The role the user acts in on the sheet, which every rule decides by: steward while a delegation holds the
     * sheet's today, else the assigned role.
     */
    public String roleOf(String sheetId, String user) {
        return delegations.actingFor(sheetId, user).isPresent() ? Role.STEWARD : assignedRoleOf(sheetId, user);
    }

    /** The user's assigned role on the sheet: clerk unless assigned another. */
    public String assignedRoleOf(String sheetId, String user) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? AND user_name = ?", ROW,
                sheetId, user).stream().findFirst().map(Role::role).orElse(Role.CLERK);
    }

    /** Assign the user a role, replacing the one assigned before. */
    public Role set(String sheetId, String user, String role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role);
        return new Role(sheetId, user, role);
    }

    /** Whether the user is a viewer on the sheet, who may change nothing. */
    public boolean isViewer(String sheetId, String user) {
        return Role.VIEWER.equals(roleOf(sheetId, user));
    }
}
